 fixture(PROFILE.replace('<h1 data-e2e="user-title">alice</h1>','<h1 data-e2e="user-title">Alice Display Name</h1><h2 data-e2e="user-subtitle">alice</h2>'),'https://www.tiktok.com/@alice');r=step(action='follow',kind='account',url='https://www.tiktok.com/@alice',mode='users');check('profile with display name as title is verified',r.get('preview') and not r.get('error'))
 fixture(PROFILE.replace('alice</h1>','Someone Else</h1>'),'https://www.tiktok.com/@alice');r=step(action='follow',kind='account',url='https://www.tiktok.com/@alice',mode='users');check('unverifiable profile still fails closed',bool(r.get('error')) and page.evaluate('clicks')==0)
 fixture('<main><h1>alice</h1><p>This account is private</p></main>','https://www.tiktok.com/@alice');r=step(kind='posts',url='https://www.tiktok.com/@alice',mode='users');check('private profile is skipped, not an error',not r.get('error') and r.get('posts')==[] and 'private' in r.get('note',''))
 fixture('<main><h1>alice</h1><p>No content</p></main>','https://www.tiktok.com/@alice');r=step(kind='posts',url='https://www.tiktok.com/@alice',mode='users');check('profile with no videos is skipped',not r.get('error') and r.get('posts')==[] and 'no videos' in r.get('note',''))
 fixture('<main><p>Couldn\'t find this account</p></main>','https://www.tiktok.com/@alice');r=step(kind='posts',url='https://www.tiktok.com/@alice',mode='users');check('missing profile is skipped',not r.get('error') and r.get('posts')==[] and 'unavailable' in r.get('note',''))
 fixture('<main><h1>alice</h1><a href="/@alice/video/111">v</a><a href="/@alice/video/222">v</a></main>','https://www.tiktok.com/@alice');r=step(kind='posts',url='https://www.tiktok.com/@alice',mode='users');check('profile with videos still returns its posts',not r.get('error') and len(r.get('posts',[]))==2)
 fixture('<main id="old"></main>','https://www.tiktok.com/@alice');page.evaluate('setTimeout(()=>{document.querySelector(\'main\').replaceWith(Object.assign(document.createElement(\'main\'),{innerHTML:\'<section data-e2e="user-page"><h1 data-e2e="user-title">alice</h1><button>Follow</button></section>\'}))},600)');r=step(action='follow',kind='account',url='https://www.tiktok.com/@alice',mode='users');check('profile re-rendered after step start is still verified',bool(r.get('preview')) and not r.get('error'))
 fixture(PROFILE,'https://www.tiktok.com/@alice');page.evaluate("()=>{document.querySelector('#follow').onclick=e=>e.currentTarget.textContent='Following'}");r=step(action='follow',dry=False,kind='account',url='https://www.tiktok.com/@alice',mode='users');check('follow confirms changed state',r.get('performed') and page.evaluate('clicks')==1)
 fixture(PROFILE.replace('>Follow<','>Following<'),'https://www.tiktok.com/@alice');page.evaluate("()=>{document.querySelector('#follow').onclick=e=>e.currentTarget.textContent='Follow'}");r=step(action='unfollow',dry=False,kind='account',url='https://www.tiktok.com/@alice',mode='users');check('explicit unfollow confirms immediate state change',r.get('performed') and page.evaluate('clicks')==1)
